import type { CardCheck } from '@/lib/flashcard-check-core'

/**
 * Card-check questions for the cards of `mcat-social-psychology-mcat`: one per card, keyed by the
 * card's exact front text. Each asks the student to use the card's idea in a
 * new situation. Gate: scripts/flashcard-checks/validate.ts.
 */
const r = String.raw

export const checks: Record<string, CardCheck> = {
  [r`What is the bystander effect and diffusion of responsibility?`]: {
    question: r`A student sends one group email to all 40 classmates asking for a copy of the notes from a lecture she missed. Recipients cannot see whether anyone has replied, and nobody answers. When she emails five classmates one at a time, four reply. Which process best explains the silence after the group email?`,
    options: [r`Social loafing on a task with pooled output`, r`Group polarization after a shared discussion`, r`Diffusion of responsibility across recipients`, r`Deindividuation caused by feeling anonymous`],
    correctAnswer: 2,
    explanation: r`With 40 recipients, each one assumes somebody else will answer, so the felt duty to help is spread thin; a one-to-one request puts the whole duty on one person. Social loafing is about reduced effort on a shared task with pooled output, group polarization needs a discussion that pushes views to an extreme, and deindividuation is disinhibited behavior under anonymity, not a failure to help.`,
  },
  [r`What is the fundamental attribution error?`]: {
    question: r`A pedestrian watches a driver run a red light and knows nothing else about him. If the pedestrian commits the fundamental attribution error, which thought is she most likely to have?`,
    options: [r`He is a reckless person by nature`, r`He must be rushing to a hospital`, r`The signal timing must be faulty`, r`Anyone would do that on this road`],
    correctAnswer: 0,
    explanation: r`The fundamental attribution error is overweighting personality and underweighting circumstances when explaining someone else's behavior, so the driver is judged to be a reckless person. A hospital emergency, a faulty signal, and a road where anyone would do the same are all situational explanations, which the error leads observers to neglect.`,
  },
  [r`Distinguish discrimination, prejudice, and ethnocentrism in social terms.`]: {
    question: r`An anthropologist lives in a village where elders are always served first and children eat last. In her report she explains the practice through the village's own beliefs about age and wisdom, without rating it against the customs she grew up with. Her approach is best described as:`,
    options: [r`An ethnocentric judgment`, r`A prejudiced attitude`, r`A discriminatory action`, r`Cultural relativism`],
    correctAnswer: 3,
    explanation: r`Cultural relativism means judging a culture by its own standards, which is what she does when she explains the custom through the villagers' beliefs. An ethnocentric judgment would rate the custom against her home culture, a prejudiced attitude is a negative feeling toward a group, and a discriminatory action is unequal treatment of a group; none of those appears here.`,
  },
  [r`What is the difference between an in-group and out-group, and in-group bias?`]: {
    question: r`A manager rates the work of several employees whose output is objectively equal. She gives noticeably higher ratings to the two who belong to the same alumni club that she does. This pattern is best described as:`,
    options: [r`Out-group homogeneity`, r`In-group favoritism`, r`Stereotype threat`, r`Group polarization`],
    correctAnswer: 1,
    explanation: r`Favoring members of a group one identifies with, when performance is equal, is in-group bias (in-group favoritism). Out-group homogeneity is seeing outsiders as all alike, stereotype threat is impaired performance from fear of confirming a stereotype, and group polarization is a shift toward a more extreme view after group discussion.`,
  },
  [r`What did Zimbardo's Stanford Prison Experiment illustrate?`]: {
    question: r`A mild-mannered student is appointed hall monitor and given a uniform, a whistle, and the power to hand out detentions. Within a week he is harsh and belittling toward classmates. Which explanation matches what the Stanford Prison Experiment is taken to illustrate?`,
    options: [r`The assigned role and setting shaped his conduct`, r`A hidden cruel trait finally revealed itself`, r`An authority ordered each harsh act directly`, r`Group discussion pushed his views to an extreme`],
    correctAnswer: 0,
    explanation: r`The study is cited to show that social roles and situational forces can override individual disposition, so the monitor role and its trappings explain the change. A hidden cruel trait is the dispositional explanation the study argues against, direct orders from an authority describe obedience research, and discussion pushing views to an extreme is group polarization.`,
  },
  [r`What factors increase interpersonal attraction?`]: {
    question: r`A student feels neutral about a lab partner. He then overhears that she told others she really enjoys working with him, and he starts to like her more. Which factor in attraction does this show?`,
    options: [r`Proximity to the person`, r`Similarity of attitudes`, r`Reciprocity of liking`, r`The halo effect at work`],
    correctAnswer: 2,
    explanation: r`We tend to like people who like us, which is reciprocity of liking; the only thing that changed was learning that she likes him. Proximity would require more physical closeness or exposure, similarity would require discovering shared attitudes, and the halo effect is letting one good trait such as attractiveness color unrelated judgments.`,
  },
  [r`What are stereotype threat and the self-fulfilling prophecy?`]: {
    question: r`An interviewer is told, wrongly, that the next applicant is cold and unfriendly. He sits farther away, asks curt questions, and makes little eye contact. The applicant, normally warm, answers stiffly, and the interviewer writes, "As expected, unfriendly." This sequence is best described as:`,
    options: [r`Stereotype threat effects`, r`A self-fulfilling prophecy`, r`The self-serving bias`, r`Self-handicapping tactics`],
    correctAnswer: 1,
    explanation: r`The interviewer's expectation changed his own behavior, which drew out the cold behavior he expected: a self-fulfilling prophecy. Stereotype threat would require the applicant's own anxiety about confirming a group stereotype, the self-serving bias concerns explaining one's own successes and failures, and self-handicapping is creating an obstacle to excuse one's own failure.`,
  },
  [r`What is group polarization and groupthink?`]: {
    question: r`Ten members of a student club each privately lean mildly toward supporting a tuition protest. They then spend an hour discussing it together. What does group polarization predict about their views afterward?`,
    options: [r`They end near a neutral midpoint`, r`They split into two opposed camps`, r`They end mildly against the protest`, r`They end more strongly in favor`],
    correctAnswer: 3,
    explanation: r`Group polarization means discussion strengthens the direction the members already leaned, so a mildly favorable group ends more strongly in favor. Moving to a neutral midpoint or to mild opposition reverses the shift, and splitting into opposed camps confuses the everyday meaning of polarized with the technical one.`,
  },
  [r`Distinguish social facilitation from social loafing.`]: {
    question: r`In a brainstorming session, six coworkers add ideas to one unsigned shared list. Each person contributes fewer ideas than when the same people list ideas alone on signed sheets. This drop is best described as:`,
    options: [r`Social loafing`, r`Social facilitation`, r`Groupthink`, r`Deindividuation`],
    correctAnswer: 0,
    explanation: r`Individuals put in less effort when their contribution is pooled and cannot be identified, which is social loafing; the unsigned shared list removes identifiability. Social facilitation is improved performance on simple tasks when others are present, groupthink is poor decision-making from suppressed dissent, and deindividuation is disinhibited behavior under anonymity and arousal.`,
  },
  [r`Distinguish dispositional from situational attribution and the self-serving bias.`]: {
    question: r`A teacher reviewing a failed exam says, "She failed because the room was hot and a fire alarm went off twice." How should the teacher's explanation be classified?`,
    options: [r`A dispositional attribution`, r`The self-serving bias`, r`A situational attribution`, r`The actor-observer bias`],
    correctAnswer: 2,
    explanation: r`The teacher locates the cause in the environment (heat and alarms), which is a situational, or external, attribution. A dispositional attribution would blame the student's ability or character, the self-serving bias applies to explaining one's own outcomes, and the actor-observer bias would have the teacher blaming the student's character rather than her circumstances.`,
  },
  [r`What is cognitive dissonance and how is it resolved?`]: {
    question: r`A committed environmentalist accepts a job that requires weekly flights and feels uneasy about it. A month later she is telling friends that the impact of air travel is exaggerated, and the unease is gone. What did she experience, and how was it resolved?`,
    options: [r`Cognitive dissonance, reduced by changing her behavior`, r`Cognitive dissonance, reduced by changing her attitude`, r`Psychological reactance, reduced by restoring freedom`, r`Stereotype threat, reduced by affirming her values`],
    correctAnswer: 1,
    explanation: r`Acting against a belief produces the discomfort called cognitive dissonance, and she removed it by revising the belief while the flying continued, so the attitude changed. Changing her behavior would mean giving up the flights, reactance is a response to a threat to one's freedom, and stereotype threat concerns fear of confirming a group stereotype.`,
  },
  [r`What did Asch's conformity study demonstrate?`]: {
    question: r`In a seminar, five students in a row state the same obviously wrong year for a famous event. The sixth student knows the correct year but repeats the wrong one so that he does not stand out. This behavior best illustrates:`,
    options: [r`Informational social influence`, r`Obedience to an authority`, r`Polarization of a group`, r`Normative social influence`],
    correctAnswer: 3,
    explanation: r`He conforms to be accepted while privately knowing the group is wrong, which is normative social influence, the kind shown in Asch's line study. Informational influence would mean he actually believed the group was right, obedience requires a command from an authority, and group polarization is a shift to a more extreme shared view after discussion.`,
  },
  [r`What did Milgram's obedience study show?`]: {
    question: r`Which of these cases is the closest parallel to what Milgram's study demonstrated?`,
    options: [r`A clerk shreds records because all her coworkers do so`, r`A clerk shreds records because a coworker asks a favor`, r`A clerk shreds records because her director orders it`, r`A clerk shreds records because she believes it is right`],
    correctAnswer: 2,
    explanation: r`Milgram showed people carrying out acts against their conscience because an authority figure instructed them, which matches the clerk following her director's order. Doing it because all coworkers do is conformity, doing it as a favor to a peer is compliance with a request, and doing it from personal conviction involves no social pressure at all.`,
  },
  [r`Distinguish conformity, compliance, and obedience.`]: {
    question: r`At a train station, a stranger with no uniform or special status asks a traveler, "Could you watch my bag for a minute?" She agrees and does so. Which form of social influence is this?`,
    options: [r`Compliance with a direct request`, r`Conformity to a group norm`, r`Obedience to an authority`, r`Polarization within a group`],
    correctAnswer: 0,
    explanation: r`She changed her behavior because of a direct request from someone with no authority over her, which defines compliance. Conformity would mean matching what a group is doing, obedience requires an order from an authority figure, and group polarization is a shift in a group's views after discussion.`,
  },
  [r`The tendency to attribute others' behavior to disposition while excusing our own as situational is the {{c1::fundamental attribution error}} (with the {{c2::actor-observer}} asymmetry).`]: {
    question: r`In a mock quiz show, a coin flip decides who writes the questions and who answers them. Questioners draw on their own specialist knowledge, so contestants miss many questions. Audience members who saw the coin flip still rate the questioners as far more knowledgeable people than the contestants. The audience's judgment illustrates:`,
    options: [r`The self-serving bias`, r`The just-world hypothesis`, r`The sleeper effect in memory`, r`The fundamental attribution error`],
    correctAnswer: 3,
    explanation: r`The audience explains the performance gap by a personal quality (knowledge) and ignores the obvious situational advantage of writing the questions, which is the fundamental attribution error. The self-serving bias concerns one's own successes and failures, the just-world hypothesis is the belief that people get what they deserve, and the sleeper effect is delayed persuasion from a discounted source.`,
  },
  [r`Stereotype threat impairs performance by loading {{c1::working memory}} with anxiety and monitoring; reduced by {{c2::self-affirmation}} and role models.`]: {
    question: r`Researchers want to reduce stereotype threat among women about to take a difficult math test. Which five-minute activity before the test is best supported as a way to do this?`,
    options: [r`Recording their gender on the test's cover sheet`, r`Writing about a value that matters most to them`, r`Hearing that the test reveals inborn math talent`, r`Being urged to prove the stereotype wrong today`],
    correctAnswer: 1,
    explanation: r`Self-affirmation, such as writing about a personally important value, eases the threat and frees working memory for the test. Recording gender makes the group identity salient, describing the test as a measure of inborn talent makes it diagnostic, and being urged to disprove the stereotype keeps attention on it; each of these adds to the monitoring and anxiety that load working memory.`,
  },
  [r`What biological correlates accompany aggression, and how do hostile and instrumental aggression differ?`]: {
    question: r`A hockey player calmly and deliberately trips an opponent who is on a breakaway, because taking a penalty is better than giving up a goal. He feels no anger toward the opponent. How should this act be classified?`,
    options: [r`Instrumental aggression, since harm is a means to a goal`, r`Hostile aggression, since harm is a means to a goal`, r`Instrumental aggression, since anger drives the act`, r`Hostile aggression, since anger drives the act`],
    correctAnswer: 0,
    explanation: r`Instrumental aggression is calculated and uses harm as a means to another end, here preventing a goal. Hostile aggression is impulsive and anger-driven with harm itself as the aim, which does not fit a calm, planned trip, and the two mixed options attach the wrong definition to the label.`,
  },
  [r`What were the outcomes of Bandura's 1961 Bobo doll experiment?`]: {
    question: r`Preschoolers watch an adult strike an inflatable clown with a toy mallet while shouting a made-up phrase. The children are never praised or rewarded for anything. Later, alone with the toy, many repeat the exact blows and the exact phrase. Which condition does this result show is NOT needed for aggression to be learned?`,
    options: [r`Watching a model carry out the specific acts`, r`Paying attention to what the model was doing`, r`Reinforcement of the child's own behavior`, r`Remembering the acts that the model performed`],
    correctAnswer: 2,
    explanation: r`The children reproduced novel acts they had only watched, with no reward to themselves, so direct reinforcement of the learner is not required for learning aggression. Watching the model, attending to the model, and remembering the acts are exactly what observational learning depends on, so none of those was shown to be unnecessary.`,
  },
  [r`What are the key numbers from Asch's line-judgment conformity study?`]: {
    question: r`A replication of Asch's line-judgment study collects 600 responses on critical trials, the trials where the confederates all give the same wrong answer. If the results match Asch's, about how many of the 600 responses will go along with the wrong majority?`,
    options: [r`About 6 of the 600 responses`, r`About 220 of the 600 responses`, r`About 300 of the 600 responses`, r`About 460 of the 600 responses`],
    correctAnswer: 1,
    explanation: r`Conformity occurred on about 37% of all critical trials, and 37% of 600 is about 220. About 460 uses 76%, which is the share of participants who conformed at least once, not the share of trials; about 6 uses the error rate of under 1% for control participants judging alone; about 300 assumes people conform on half of the trials.`,
  },
  [r`Milgram obedience fell to about {{c1::30}}% with touch proximity and about {{c2::20}}% when the experimenter gave orders by phone.`]: {
    question: r`Consider three versions of Milgram's procedure: the baseline (learner in the next room, experimenter present), a touch version (the teacher must press the learner's hand onto a shock plate), and a phone version (the experimenter leaves and gives orders by telephone). Which order runs from the highest to the lowest rate of full obedience?`,
    options: [r`Touch, then baseline, then phone`, r`Phone, then baseline, then touch`, r`Baseline, then phone, then touch`, r`Baseline, then touch, then phone`],
    correctAnswer: 3,
    explanation: r`Full obedience was about 65% at baseline, about 30% when the teacher had to touch the learner, and about 20% when orders came by phone. Putting phone above touch swaps the 20% and 30% figures, and any order that puts a variation above baseline ignores that both bringing the victim closer and moving the authority away reduce obedience.`,
  },
  [r`Group polarization works through {{c1::persuasive arguments}} (hearing novel points favoring the lean) and {{c2::social comparison}} (outdoing the group norm).`]: {
    question: r`A committee leans toward a risky investment. During discussion one member realizes the others are bolder than she had assumed. Wanting to be seen favorably, she voices a position even bolder than the group's average, without having heard any new argument. Which mechanism of group polarization is at work?`,
    options: [r`Social comparison`, r`Persuasive arguments`, r`Pluralistic ignorance`, r`Diffusion of responsibility`],
    correctAnswer: 0,
    explanation: r`She shifts in order to compare well against the group norm, not because of new information, which is the social comparison mechanism. The persuasive arguments mechanism requires hearing novel points that favor the lean, pluralistic ignorance is misreading others' calm as a sign nothing is wrong, and diffusion of responsibility explains why bystanders fail to help.`,
  },
  [r`What are classic peripheral cues in persuasion, and when do they dominate?`]: {
    question: r`A toothpaste commercial offers no real evidence but features a well-liked athlete and upbeat music. According to the elaboration likelihood model, which viewer is most likely to be persuaded by it?`,
    options: [r`A dentist who is comparing the ingredient data`, r`A shopper researching brands for a bulk order`, r`A tired viewer half-watching it while cooking`, r`A viewer who enjoys picking apart every claim`],
    correctAnswer: 2,
    explanation: r`Peripheral cues such as an attractive source and music dominate when relevance is low and the audience is tired or distracted, as with the viewer half-watching while cooking. The dentist and the shopper have high personal relevance, and the viewer who enjoys analyzing claims has a high need for cognition; all three would scrutinize the weak argument.`,
  },
  [r`What are the main criticisms of Milgram's obedience studies?`]: {
    question: r`In Milgram's procedure, a participant says, "I want to stop now." The experimenter replies, "You have no other choice; you must go on." Which ethical criticism of the study does this exchange most directly support?`,
    options: [r`It used a sample that was too small to generalize`, r`It lacked any random assignment to conditions`, r`It stored data in a way that broke confidentiality`, r`It compromised the participant's right to withdraw`],
    correctAnswer: 3,
    explanation: r`The verbal prods pressured participants to continue after they asked to stop, which undermines the right to withdraw, one of the main ethical criticisms along with deception and severe stress. Sample size and random assignment are methodological points, not ethical ones raised by this exchange, and nothing in the exchange concerns confidentiality of data.`,
  },
  [r`What happened in the Stanford Prison Experiment, and why is it now heavily criticized?`]: {
    question: r`Recordings from the Stanford Prison Experiment show the lead researcher, acting as prison superintendent, instructing the guards on how to treat prisoners. Which conclusion of the study does this evidence most weaken?`,
    options: [r`That the participants were assigned roles by chance`, r`That guards turned harsh on their own from the role`, r`That the study was stopped earlier than planned`, r`That some prisoners showed distress in the study`],
    correctAnswer: 1,
    explanation: r`If guards were coached, their harshness may reflect following the researcher's instructions and demand characteristics, not spontaneous absorption of a role. The coaching evidence does not bear on whether roles were assigned by chance, whether the study ended after 6 of the planned 14 days, or whether prisoners were distressed.`,
  },
  [r`What is the Ringelmann rope-pulling effect, and what conditions eliminate it?`]: {
    question: r`A rowing coach measures each rower's pulling force alone and then in an eight-person boat, where only the crew's combined force is displayed. Each rower pulls less hard in the boat. Which change is most likely to remove this drop in effort?`,
    options: [r`Add two more rowers to the same boat`, r`Keep showing only the crew's total force`, r`Show each rower's force output by name`, r`Tell the crew this session will not count`],
    correctAnswer: 2,
    explanation: r`The Ringelmann effect is social loafing: effort falls when output is pooled and individuals cannot be identified, so displaying each rower's force by name restores effort. Adding rowers makes the group larger and the loafing worse, continuing to show only the total keeps contributions hidden, and saying the session does not count makes the task matter less.`,
  },
  [r`Same crowd, opposite effects: when does the presence of others improve versus worsen your performance?`]: {
    question: r`A swim coach wants the fastest possible times from experienced swimmers doing a stroke they have practiced for years. Based on research on the presence of others, which arrangement should produce the best performance?`,
    options: [r`Post each swimmer's own time with a crowd watching`, r`Record only the team's total with a crowd watching`, r`Record only the team's total with nobody watching`, r`Teach a brand new stroke with a crowd watching`],
    correctAnswer: 0,
    explanation: r`Performance improves when the task is well practiced and each person's output is individually evaluated in front of others, which is social facilitation. Recording only the team total makes individual output unidentifiable and invites loafing, with or without a crowd, and a brand new stroke is a novel task on which an audience's arousal impairs performance.`,
  },
  [r`In the {{c1::sleeper}} effect, a message from a discredited source gains influence over time because {{c2::source memory}} fades faster than the message.`]: {
    question: r`Participants read a persuasive article about a supplement and are then told it came from a tabloid known for errors. Measured right away, their attitudes barely change. If the sleeper effect occurs, what will be found six weeks later?`,
    options: [r`Less persuasion, since the message is forgotten first`, r`Less persuasion, since the source is now recalled`, r`More persuasion, since the tabloid has gained trust`, r`More persuasion, since the source is forgotten first`],
    correctAnswer: 3,
    explanation: r`In the sleeper effect the discounting cue (the unreliable source) fades from memory faster than the message, so the message's influence rises with time. Predicting less persuasion describes ordinary decay of a message, and the tabloid does not become more trusted; the reader simply no longer connects the message with it.`,
  },
  [r`In ELM experiments, what variable flips people from peripheral to central processing?`]: {
    question: r`A researcher wants college students to weigh the quality of the arguments for a new graduation exam instead of relying on who is endorsing it. Based on elaboration likelihood experiments, what should the students be told?`,
    options: [r`The exam was proposed by a famous professor`, r`The exam starts at their own college next year`, r`The exam starts at a distant college next year`, r`The exam starts at their own college in ten years`],
    correctAnswer: 1,
    explanation: r`Personal relevance is the variable that moves people to central processing, and an exam at their own college next year affects them directly. A policy at a distant college or one ten years away has low relevance, so students fall back on cues, and naming a famous professor supplies exactly the kind of source cue that peripheral processing uses.`,
  },
  [r`What were the key numbers in Darley and Latane's seizure (bystander) study?`]: {
    question: r`A lab repeats Darley and Latané's seizure study. Over an intercom, 20 participants each believe they are the only one hearing a person have a seizure, and 100 participants each believe four others are also listening. If the original rates hold, how many in each condition help by the end?`,
    options: [r`17 of 20 alone; 31 of 100 with four others`, r`17 of 20 alone; 85 of 100 with four others`, r`6 of 20 alone; 85 of 100 with four others`, r`10 of 20 alone; 50 of 100 with four others`],
    correctAnswer: 0,
    explanation: r`The original rates were 85% helping when alone and 31% when four other bystanders were believed present; 85% of 20 is 17 and 31% of 100 is 31. Equal rates in both conditions ignore diffusion of responsibility, the option with 6 of 20 and 85 of 100 reverses the two conditions, and 50% in both matches neither finding.`,
  },
  [r`How does Batson's empathy-altruism hypothesis differ from egoistic accounts of helping?`]: {
    question: r`Observers feel strong empathic concern for a woman receiving unpleasant shocks. They are told they are free to leave immediately and will not see any more, or they may trade places with her. What does Batson's empathy-altruism hypothesis predict?`,
    options: [r`They leave, because leaving ends their own distress`, r`They help only when they expect to be repaid later`, r`They trade places even though leaving is easy`, r`They trade places only when leaving is made hard`],
    correctAnswer: 2,
    explanation: r`Batson holds that empathic concern produces truly altruistic helping, which continues even when escaping the distressing scene is easy. Leaving to end one's own distress, and helping only when escape is hard, are both predictions of the egoistic negative-state relief account, and helping for expected repayment is reciprocity, another egoistic motive.`,
  },
  [r`What did Steele and Aronson's 1995 stereotype threat experiments show?`]: {
    question: r`Older adults are randomly assigned to take the same word-list task under one of two labels: "a test of memory" or "an exercise in forming impressions." A common stereotype holds that memory declines with age. Applying the logic of Steele and Aronson's experiments, what result is expected for the older adults?`,
    options: [r`Lower scores only under the impressions label`, r`Lower scores only under the memory-test label`, r`Equally low scores under both of the labels`, r`Higher scores under the memory-test label`],
    correctAnswer: 1,
    explanation: r`Steele and Aronson found that performance dropped only when the task was framed as diagnostic of the stereotyped ability, so the memory-test label should lower scores and the neutral label should not. Equal scores under both labels ignores that framing was the manipulated cause, and higher scores under the threatening label reverses the effect.`,
  },
  [r`What is effort justification, and what is the classic evidence for it?`]: {
    question: r`Three groups join the same club. One group must pass a grueling week-long entry trial, one fills out a short form, and one is simply added to the roster. All then sit through the same dull first meeting. Which group does dissonance theory predict will rate the meeting most favorably?`,
    options: [r`The short-form group, since it felt the least stress`, r`The roster group, since it has nothing to resent`, r`All three equally, since the meeting was the same`, r`The entry-trial group, to justify what it endured`],
    correctAnswer: 3,
    explanation: r`This is effort justification: having suffered to get in, finding the club dull would be dissonant, so the entry-trial group resolves the conflict by valuing the club more. The short-form and roster groups paid little, so they have nothing to justify, and equal ratings would ignore that the cost paid changes how the same meeting is judged.`,
  },
  [r`What did LaPiere's 1934 study show, and when do attitudes actually predict behavior?`]: {
    question: r`Four people all say they favor blood donation. Whose stated attitude is most likely to predict that the person actually donates at next month's drive?`,
    options: [r`Eli, whose view came from one poster seen years ago`, r`Fay, who holds the view weakly and seldom recalls it`, r`Dana, whose view formed when a transfusion saved her`, r`Gus, who says it only when his coworkers press him`],
    correctAnswer: 2,
    explanation: r`Attitudes predict behavior best when they are strong, accessible, and formed by direct experience, as Dana's is. Eli's attitude comes from indirect, distant exposure, Fay's is weak and rarely accessible, and Gus's statement reflects social pressure, the kind of gap between words and actions that LaPiere documented.`,
  },
  [r`Hamilton's rule: altruism toward kin evolves when {{c1::rB > C}}, the benefit weighted by genetic relatedness exceeding the cost to the helper.`]: {
    question: r`A helping act costs the helper 1 unit of reproductive success and gives the recipient 3 units. Relatedness is r = 0.5 for a full sibling and r = 0.125 for a first cousin. According to Hamilton's rule, toward which relative is this act favored by selection?`,
    options: [r`Toward the sibling but not toward the cousin`, r`Toward the cousin but not toward the sibling`, r`Toward both the sibling and the cousin`, r`Toward neither the sibling nor the cousin`],
    correctAnswer: 0,
    explanation: r`Hamilton's rule requires rB > C. For the sibling, 0.5 × 3 = 1.5, which exceeds the cost of 1; for the cousin, 0.125 × 3 = 0.375, which does not. Choosing both ignores the weighting by r, choosing neither compares the unweighted cost wrongly, and choosing only the cousin inverts the effect of relatedness.`,
  },
  [r`Which situational factors increase helping, and what did the Good Samaritan seminary study show?`]: {
    question: r`Two students each walk across campus to give a short talk on the duty to help strangers, and each passes a man slumped in a doorway. One has just been told she is late; the other has been told he has a few minutes to spare. Based on the seminary study, what best predicts which of them stops?`,
    options: [r`How religious each student reports being`, r`How relevant the talk's topic is to helping`, r`How caring each student rates his own nature`, r`How much time pressure each student is under`],
    correctAnswer: 3,
    explanation: r`Darley and Batson found that only 10% of hurried students helped versus 63% of unhurried ones, so time pressure was the deciding factor. Religiosity and self-rated caring are dispositional factors that mattered little, and having a talk about helping in mind did not make hurried students stop.`,
  },
  [r`In Bandura's 1965 follow-up, what did vicarious punishment change, and what did incentives reveal?`]: {
    question: r`Children watch a film in which a model is scolded for hitting a doll, and afterward they imitate very little. The experimenter then offers a sticker for every act from the film they can reproduce, and they reproduce as many acts as children who saw the model praised. What does this show?`,
    options: [r`They had not learned the acts until stickers were offered`, r`They had learned the acts but held back from doing them`, r`Seeing the model scolded erased their memory of the acts`, r`The stickers taught them the acts through gradual shaping`],
    correctAnswer: 1,
    explanation: r`The model's punishment suppressed performance, not learning: once an incentive was offered, the children showed they had acquired the acts all along. The acts could not have been learned from the stickers or shaped by them, because they were reproduced at once, and memory was clearly intact since the acts were performed accurately.`,
  },
  [r`Berkowitz's revision: frustration causes aggression only via {{c1::negative affect}}, and aggressive cues such as guns ({{c2::the weapons effect}}) amplify it.`]: {
    question: r`Which finding supports Berkowitz's revised account of aggression over the original frustration-aggression hypothesis?`,
    options: [r`Every blocked goal is followed by some aggressive act`, r`Aggression appears only after a goal has been blocked`, r`Painful heat raises aggression with no goal blocked`, r`Visible weapons reduce aggression in angered people`],
    correctAnswer: 2,
    explanation: r`Berkowitz argued that any aversive event that creates negative affect, such as pain or heat, can prime aggression, so aggression without a blocked goal fits his revision and not the original. The two blocked-goal statements restate the original hypothesis that frustration always precedes aggression, and weapons increase aggressive responding in his account (the weapons effect), they do not reduce it.`,
  },
  [r`The {{c1::actor-observer}} bias: we attribute our own behavior to the situation but others' identical behavior to their disposition.`]: {
    question: r`A student says, "I skipped the reading because my week was overloaded," but says of her roommate, who skipped the same reading, "She just isn't serious about school." Which account best explains this asymmetry?`,
    options: [r`Actors notice their situation; observers notice the person`, r`Actors claim their successes and disown their failures`, r`Observers assume that people get what they deserve`, r`Observers see members of other groups as all alike`],
    correctAnswer: 0,
    explanation: r`This is the actor-observer bias, explained by perceptual salience: when we act, our circumstances fill our view, but when we watch someone else, the person is what stands out. Claiming successes and disowning failures is the self-serving bias, believing people get what they deserve is the just-world hypothesis, and seeing other groups as all alike is out-group homogeneity.`,
  },
  [r`Asch's effect was mostly {{c1::normative}} influence (public compliance, private disbelief); Sherif's autokinetic norms show {{c2::informational}} influence.`]: {
    question: r`A tourist in an unfamiliar city has no idea which side of the escalator people are meant to stand on. She watches the locals, copies them, and continues to stand on that side on later trips when nobody else is around, believing it is the correct way. Which description fits?`,
    options: [r`Normative influence with private acceptance`, r`Informational influence with private acceptance`, r`Normative influence with public compliance only`, r`Informational influence with public compliance only`],
    correctAnswer: 1,
    explanation: r`The situation is ambiguous, she uses others as a source of information, and the behavior persists when she is alone, so the norm has been internalized: informational influence with private acceptance, as in Sherif's autokinetic study. Normative influence is conforming to fit in while privately disagreeing, as in Asch's study, and it produces public compliance that disappears in private.`,
  },
  [r`Central-route persuasion requires both {{c1::motivation}} and {{c2::ability}} to elaborate, and it produces durable, behavior-predictive attitude change.`]: {
    question: r`A patient cares a great deal about an upcoming surgery and wants to evaluate the consent information carefully. While she reads it, a loud alarm test keeps interrupting her. What does the elaboration likelihood model predict about her processing?`,
    options: [r`Central processing, since her motivation is enough`, r`Central processing, since the noise adds arousal`, r`Peripheral processing, since her motivation is low`, r`Peripheral processing, since her ability is impaired`],
    correctAnswer: 3,
    explanation: r`Central-route processing needs both motivation and ability to elaborate; distraction removes the ability even when motivation is high, so she is pushed toward peripheral processing. Motivation alone is not enough, arousal from noise does not improve scrutiny of arguments, and her motivation is high, not low.`,
  },
  [r`What is the pattern and function of the self-serving bias, and when does it reverse?`]: {
    question: r`A patient with major depression is promoted in the spring and loses an important client in the fall. Which pair of explanations shows the reversal of the self-serving bias that is often seen in depression?`,
    options: [r`The promotion was luck; losing the client was my fault`, r`The promotion was my skill; losing the client was bad luck`, r`The promotion was my skill; losing the client was my fault`, r`The promotion was luck; losing the client was bad luck`],
    correctAnswer: 0,
    explanation: r`The usual self-serving pattern credits successes to oneself and blames failures on outside causes; the reversed pattern attributes the success to luck and the failure to oneself. Skill for the promotion with bad luck for the loss is the ordinary self-serving bias, and the two remaining pairs treat both events the same way, so they show no bias in either direction.`,
  },
  [r`Kelley's covariation model: high {{c1::consensus}}, high {{c2::distinctiveness}}, and high consistency point to a situational (external) attribution.`]: {
    question: r`Sam complains loudly about the Harbor Hotel on every one of his stays there (high consistency), and few other guests complain about it (low consensus). Which additional fact would complete the pattern that leads to a dispositional attribution in Kelley's covariation model?`,
    options: [r`Sam complains about no other hotel he stays in`, r`Most other guests complain about that hotel too`, r`Sam complains about nearly every hotel he visits`, r`Sam complained on only one of his five stays there`],
    correctAnswer: 2,
    explanation: r`Low consensus, high consistency, and low distinctiveness together point to the person; low distinctiveness means Sam behaves this way toward many targets, that is, at nearly every hotel. Complaining about no other hotel is high distinctiveness, which points toward the hotel, most guests complaining contradicts the stated low consensus, and one complaint in five stays contradicts the stated high consistency.`,
  },
  [r`In Asch's variations, what most sharply reduced conformity?`]: {
    question: r`In one variation of Asch's line study, a confederate breaks from the majority but gives a different wrong answer, so the participant still has nobody agreeing with the correct line. What happens to the participant's conformity to the majority?`,
    options: [r`It stays the same, since the dissenter is wrong too`, r`It rises, since two wrong answers add to the doubt`, r`It dips only slightly, since only correct allies help`, r`It drops sharply, since the group is not unanimous`],
    correctAnswer: 3,
    explanation: r`A single dissenter, even an inaccurate one, cut conformity to roughly 5 to 9 percent, because what matters is that the majority is no longer unanimous. The other options assume the dissenter must be correct to help, or that more wrong answers add pressure, and both are contradicted by this variation.`,
  },
  [r`What are the antecedents and hallmark symptoms of groupthink (Janis)?`]: {
    question: r`A tightly knit board is finalizing a plan. One member receives a consultant's sharply critical report and decides not to pass it to the others, saying the team should stay focused and united. Which symptom of groupthink does this member show?`,
    options: [r`Self-censorship of doubt`, r`Acting as a mindguard`, r`Illusion of invulnerability`, r`Stereotyping of outgroups`],
    correctAnswer: 1,
    explanation: r`A mindguard shields the group from information that could disturb its consensus, which is what withholding the critical report does. Self-censorship is keeping one's own doubts quiet, the illusion of invulnerability is excessive optimism about the plan, and stereotyping outgroups is dismissing rivals or critics as weak or foolish.`,
  },
  [r`Festinger and Carlsmith (1959): what was the design, and which group changed its attitude?`]: {
    question: r`In a study modeled on Festinger and Carlsmith's, participants sort spools for an hour and are then paid either 2 dollars or 40 dollars to tell the next person that the task was enjoyable. Later, the 2-dollar group privately rates the task as fairly enjoyable and the 40-dollar group rates it as dull. Why did the 40-dollar group's opinion not change?`,
    options: [r`The large payment already justified telling the lie`, r`The large payment made the task feel like real work`, r`The large payment raised their arousal and dissonance`, r`The large payment made them doubt the cover story`],
    correctAnswer: 0,
    explanation: r`A large payment is sufficient external justification for saying something untrue, so little dissonance arises and there is no pressure to change the attitude. The small payment is insufficient justification, so that group reduces dissonance by deciding the task was enjoyable. Higher pay lowers dissonance, it does not raise it, and the result does not depend on doubting the cover story or seeing the task as work.`,
  },
  [r`When does Bem's self-perception theory explain attitude change better than dissonance theory?`]: {
    question: r`A shopper has never formed an opinion about a new brand of tea. Noticing that she has bought it three weeks in a row, she concludes, "I suppose I like it." She felt no tension or discomfort at any point. Which theory best explains how her attitude formed?`,
    options: [r`Cognitive dissonance theory`, r`Social comparison theory`, r`Self-perception theory`, r`Elaboration likelihood model`],
    correctAnswer: 2,
    explanation: r`Bem's self-perception theory says that when prior attitudes are weak or absent, people infer their attitudes from watching their own behavior, with no arousal involved. Dissonance theory needs an aversive tension between a behavior and an existing attitude, which she lacks; social comparison is evaluating oneself against others, and the elaboration likelihood model concerns how persuasive messages are processed.`,
  },
  [r`Latane and Darley's helping sequence: notice the event, {{c1::interpret it as an emergency}}, {{c2::take responsibility}}, know how to help, then act.`]: {
    question: r`On a crowded beach, everyone hears a swimmer screaming for help, and everyone agrees it is a real emergency. Each person stays put, thinking that the lifeguard or one of the stronger swimmers will go. At which step of Latané and Darley's helping sequence does helping break down?`,
    options: [r`Noticing that something happened`, r`Taking personal responsibility`, r`Interpreting it as an emergency`, r`Knowing what form of help to give`],
    correctAnswer: 1,
    explanation: r`The event was noticed and correctly interpreted as an emergency, so the failure comes at the next step, taking responsibility, where diffusion of responsibility operates. A breakdown at interpretation would be pluralistic ignorance, with people reading each other's calm as a sign of no danger, and nothing suggests the bystanders got as far as deciding how to help.`,
  },
  [r`What behavioral consequence does the just-world hypothesis predict?`]: {
    question: r`Observers watch a woman receive painful shocks for making errors on a task. They are told the session will continue and that they can neither stop it nor compensate her. What does the just-world hypothesis predict the observers will do?`,
    options: [r`Rate her character more positively than before`, r`Blame the cruel nature of the experimenter`, r`Offer to take her place in the next session`, r`Rate her character more negatively than before`],
    correctAnswer: 3,
    explanation: r`People who believe the world is fair protect that belief when they cannot help a victim by deciding she deserved it, so they derogate her character. Rating her more positively would make her suffering seem even less fair, blaming the experimenter is a different attribution that leaves the world unjust, and offering to trade places is ruled out and reflects empathy, not just-world thinking.`,
  },
  [r`{{c1::Lowballing}} secures commitment and then raises the cost; {{c2::foot-in-the-door}} escalates from a small request via self-perception.`]: {
    question: r`Which sales sequence is an example of lowballing, as distinct from the foot-in-the-door technique?`,
    options: [r`Agree to a short survey, then to a long home visit`, r`Refuse a costly plan, then accept a cheaper plan`, r`Agree to a quoted price, then learn of added fees`, r`Accept a free sample, then buy the full product`],
    correctAnswer: 2,
    explanation: r`Lowballing secures commitment to a deal and then raises its cost, and the commitment holds; agreeing to a price and then meeting added fees fits that. A small request followed by a larger one is foot-in-the-door, a refused large request followed by a smaller one is door-in-the-face, and a free sample before a purchase works through reciprocity.`,
  },
  [r`{{c1::Deindividuation}} = anonymity plus arousal and diffused responsibility, producing reduced self-awareness and disinhibited, group-norm-driven behavior.`]: {
    question: r`Participants in a shock study wear outfits that hide their identity. Half are dressed in nurse-style uniforms and half in hooded robes. Given that deindividuation makes people highly responsive to the local group norm, which result is expected?`,
    options: [r`Fewer shocks in nurse uniforms, more in hooded robes`, r`More shocks in both, since anonymity always disinhibits`, r`Fewer shocks in both, since the outfits distract them`, r`Equal shocks in both, since outfits cannot carry norms`],
    correctAnswer: 0,
    explanation: r`Deindividuation does not make people randomly antisocial; reduced self-awareness makes them follow whatever norm the setting cues. A nurse uniform cues caring, so shocks fall, while a hooded robe cues aggression, so shocks rise. Predicting more shocks in both treats anonymity as purely disinhibiting, and the other two options ignore the role of the cued norm.`,
  },
  [r`Zajonc: an audience strengthens the {{c1::dominant}} response, improving {{c2::easy or well-learned}} tasks and impairing difficult ones.`]: {
    question: r`A pianist performs two pieces for an audience: one she has played hundreds of times and one difficult piece she learned last week. According to Zajonc's account, how does the audience affect her playing compared with practicing alone?`,
    options: [r`Both pieces improve, since arousal sharpens focus`, r`Both pieces worsen, since arousal causes anxiety`, r`The familiar piece worsens; the new piece improves`, r`The familiar piece improves; the new piece worsens`],
    correctAnswer: 3,
    explanation: r`An audience raises arousal, which strengthens the dominant response. On a well-learned piece the dominant response is correct, so performance improves; on a newly learned, difficult piece the dominant responses are often errors, so performance gets worse. The remaining options treat arousal as uniformly helpful or harmful, or reverse the pattern.`,
  },
  [r`The {{c1::ultimate attribution error}} extends the FAE to groups: outgroup failures reflect disposition, outgroup successes reflect luck or special advantage.`]: {
    question: r`A sports fan says that players from a rival school lose because "they are lazy people." When the same rival team wins, he says, "The referees handed it to them." Which bias does this pattern show?`,
    options: [r`The actor-observer bias`, r`The ultimate attribution error`, r`The self-serving bias`, r`The out-group homogeneity effect`],
    correctAnswer: 1,
    explanation: r`The ultimate attribution error applies attribution bias at the group level: an out-group's failures are blamed on its character and its successes are explained away by luck or special advantage. The actor-observer bias contrasts one's own behavior with another individual's, the self-serving bias is about one's own outcomes, and out-group homogeneity is seeing out-group members as all alike.`,
  },
  [r`What were Milgram's baseline obedience findings?`]: {
    question: r`A researcher imagines running Milgram's baseline procedure with 200 new participants. If the original results held exactly, what would be found?`,
    options: [r`About 130 reach 450 volts; none stop before 300 volts`, r`About 130 reach 450 volts; about 70 stop before 300 volts`, r`About 2 reach 450 volts; nearly all stop before 300 volts`, r`About 60 reach 450 volts; none stop before 300 volts`],
    correctAnswer: 0,
    explanation: r`At baseline 65% went to the 450-volt maximum, and 65% of 200 is 130; every participant went to at least 300 volts, so none stop before that point. Having about 70 stop before 300 volts ignores that second finding, about 2 reaching the maximum is the psychiatrists' prediction of under 1%, and about 60 uses a 30% rate from a later variation.`,
  },
  [r`Dissonance can be reduced by changing the {{c1::behavior}}, changing or adding {{c2::cognitions}}, or trivializing the inconsistency.`]: {
    question: r`A man on a strict diet eats a slice of cake at a party. Afterward he tells himself, "One slice is such a small thing that it is not worth thinking about," and his discomfort fades. Which route of dissonance reduction did he use?`,
    options: [r`Changing the behavior itself`, r`Adding a consonant cognition`, r`Trivializing the inconsistency`, r`Denying that he made a choice`],
    correctAnswer: 2,
    explanation: r`He kept both the diet and the fact that he ate the cake but decided the conflict was too minor to matter, which is trivializing the inconsistency. Changing the behavior would mean not eating cake again or abandoning the diet, adding a consonant cognition would be a new supporting belief such as "I will run extra tomorrow," and he never claimed the choice was forced on him.`,
  },
  [r`A cancer patient who compares herself with sicker patients feels better; comparing with healthier ones motivates but distresses. Name the theory.`]: {
    question: r`A runner finishes in the middle of the pack and feels discouraged. She then scrolls through the results of the slower finishers and feels noticeably better about her race. What is she doing?`,
    options: [r`Upward social comparison`, r`Downward social comparison`, r`Self-serving attribution`, r`Self-handicapping in advance`],
    correctAnswer: 1,
    explanation: r`Comparing oneself with people who did worse is downward social comparison, which protects mood and self-esteem. Upward comparison would mean looking at faster finishers, which can motivate but tends to hurt self-evaluation; a self-serving attribution would blame her time on outside causes, and self-handicapping means creating an obstacle before the race.`,
  },
  [r`Teachers told that certain randomly chosen students were late bloomers saw those students gain more on later testing. Name the effect and its mediator.`]: {
    question: r`A swim coach is told, falsely, that five randomly chosen swimmers have exceptional potential. By the end of the season, electronic timing shows that those five improved more than their teammates. What is the most likely mediator of this result?`,
    options: [r`The five swimmers had more talent from the start`, r`The five swimmers feared confirming a stereotype`, r`The coach recorded their race times less honestly`, r`The coach gave them more feedback and attention`],
    correctAnswer: 3,
    explanation: r`This is the Pygmalion effect: the coach's expectation changed the warmth, feedback, and opportunities offered to those swimmers, and that changed their performance. Greater initial talent is ruled out by random selection, biased timing is ruled out by the electronic timing, and fear of confirming a stereotype describes stereotype threat, which would lower performance.`,
  },
  [r`Allport's contact hypothesis names four conditions under which contact reduces prejudice. What are they?`]: {
    question: r`Two rival student groups are assigned to a school-sponsored fundraiser. Both groups share one target and must work together to reach it, but members of one group are made supervisors and members of the other may only take their orders. Which of Allport's conditions for reducing prejudice is missing?`,
    options: [r`Equal status in the situation`, r`Support from the authorities`, r`A common goal for both groups`, r`Cooperation between the groups`],
    correctAnswer: 0,
    explanation: r`Allport's four conditions are equal status, common goals, cooperation, and support from authorities. Here the school sponsors the event, the target is shared, and the groups must work together, but a supervisor and subordinate arrangement gives the groups unequal status within the situation.`,
  },
  [r`Cialdini's six principles of influence: reciprocity, commitment and consistency, {{c1::social proof}}, authority, liking, and {{c2::scarcity}}.`]: {
    question: r`A shopping site displays two messages beside a jacket: first, "Chosen by 9 out of 10 shoppers like you," and second, "Only 2 left at this price." Which of Cialdini's principles do the two messages use, in that order?`,
    options: [r`Scarcity, then social proof`, r`Authority, then reciprocity`, r`Social proof, then scarcity`, r`Liking, then commitment`],
    correctAnswer: 2,
    explanation: r`Pointing to what most other people choose is social proof, and stressing limited availability is scarcity. The reversed order mislabels each message; authority would require an expert or official endorsement, reciprocity a gift or favor given first, liking a pleasant or similar source, and commitment an earlier pledge from the shopper.`,
  },
  [r`A clinician reports egalitarian views yet shows faster pairing of one race with negative words on the IAT. What does this show, and what is the caveat?`]: {
    question: r`A hospital proposes giving every job applicant the Implicit Association Test and rejecting those whose scores indicate bias. What is the strongest objection based on what is known about the test?`,
    options: [r`Implicit attitudes always match what people report`, r`One person's score is too unstable to judge them by`, r`The test only measures deliberate, stated beliefs`, r`Group averages on the test hold no information`],
    correctAnswer: 1,
    explanation: r`Individual IAT scores have modest test-retest reliability and only weakly predict a given person's behavior, so the test suits research on groups and not decisions about individuals. Implicit and explicit attitudes can come apart, the test captures automatic associations and not stated beliefs, and group-level averages are informative.`,
  },
  [r`A patient told firmly that he must quit smoking becomes more insistent on his right to smoke. Name the phenomenon and the counseling implication.`]: {
    question: r`A patient who drinks heavily bristles whenever he is told what to do. Which opening statement from a clinician is most likely to avoid triggering psychological reactance?`,
    options: [r`You have no choice here. You must cut down starting today.`, r`Every expert agrees that you need to cut down right away.`, r`If you refuse to cut down, I cannot keep treating you.`, r`This is your decision. What might make cutting down worth it?`],
    correctAnswer: 3,
    explanation: r`Reactance arises when people feel their freedom is threatened, and they restore it by resisting. Affirming that the decision is his and asking for his own reasons, as in motivational interviewing, removes the threat. The statements that deny choice, cite unanimous experts as a demand, or threaten to end treatment all pressure him and invite resistance.`,
  },
  [r`{{c1::Self-handicapping}} means creating an obstacle in advance so that failure can be attributed {{c2::externally}} while success is credited doubly.`]: {
    question: r`A pianist who is worried about failing an audition stops practicing the week before and goes out late the night before. Afterward she says, "I barely rehearsed, so the result says nothing about my talent." What is this strategy called?`,
    options: [r`Self-serving bias`, r`Learned helplessness`, r`Self-handicapping`, r`Stereotype threat`],
    correctAnswer: 2,
    explanation: r`She created an obstacle in advance so that failure could be blamed on something other than her ability, which is self-handicapping. The self-serving bias is an after-the-fact attribution with no obstacle built beforehand, learned helplessness is giving up after uncontrollable outcomes, and stereotype threat involves fear of confirming a stereotype about one's group.`,
  },
  [r`At Robbers Cave, hostility between two boys' camps fell only when they had to repair a shared water supply. What theory and remedy does this illustrate?`]: {
    question: r`Two departments in a company have grown hostile while competing for a single bonus pool. According to realistic conflict theory and the Robbers Cave findings, which step is most likely to reduce the hostility?`,
    options: [r`A joint project that neither can finish alone`, r`A shared lunch hour with no assigned task`, r`A new contest between them for a larger prize`, r`A talk on the good qualities of the other side`],
    correctAnswer: 0,
    explanation: r`Hostility that comes from competition over scarce resources fell at Robbers Cave only when the groups faced superordinate goals that required real cooperation. Mere contact, such as a shared lunch, did not help, another contest adds more competition, and a talk about the other group does not change the competitive structure.`,
  },
  [r`Subjects who guess a study's hypothesis behave so as to confirm it. Name this threat and the design features that control it.`]: {
    question: r`After watching a sad film, participants are handed a mood questionnaire. Many guess that the researchers expect the film to cause sadness, and they overstate how sad they feel. Which design change most directly controls this problem?`,
    options: [r`Recruiting a larger and more varied sample`, r`Waiting longer before giving the questionnaire`, r`Using a longer and more reliable mood scale`, r`Using a cover story that hides the hypothesis`],
    correctAnswer: 3,
    explanation: r`Participants are responding to demand characteristics, cues that reveal the hypothesis. Blinding them with a cover story or placebo-style controls removes the cue. A larger sample, a delay, or a more reliable scale would not stop participants from guessing the hypothesis and acting to confirm it.`,
  },
  [r`Boys assigned to groups by a coin flip still allocated more money to their own group. Name the paradigm and the theory it supports.`]: {
    question: r`At a conference, attendees who are strangers receive red or blue wristbands at random. They never interact and no prize is at stake, yet they rate people wearing their own color as more likeable. Which theory best accounts for this?`,
    options: [r`Realistic conflict theory`, r`Social identity theory`, r`Social exchange theory`, r`Frustration-aggression theory`],
    correctAnswer: 1,
    explanation: r`As in Tajfel's minimal group paradigm, arbitrary categorization alone produces in-group favoritism, which social identity theory explains through self-esteem drawn from group membership. Realistic conflict theory requires competition for scarce resources, social exchange theory weighs rewards and costs in relationships, and frustration-aggression needs an aversive event; none is present.`,
  },
  [r`The {{c1::halo}} effect spreads one positive trait to unrelated judgments; its mirror image is the {{c2::horns}} effect.`]: {
    question: r`A teacher learns that a student keeps a very messy desk. Afterward the teacher rates the same student's essays as less insightful and her excuses as less honest, although nothing about her work has changed. Which bias is this?`,
    options: [r`The horns effect`, r`The halo effect`, r`The sleeper effect`, r`The mere exposure effect`],
    correctAnswer: 0,
    explanation: r`One negative trait is spreading to unrelated judgments, which is the horns effect, the mirror image of the halo effect. The halo effect spreads a positive trait, the sleeper effect is delayed persuasion from a discounted source, and mere exposure is increased liking from repeated contact.`,
  },
  [r`{{c1::Social exchange}} theory says relationships persist when rewards exceed costs; {{c2::equity}} theory adds that being over-benefited also distresses.`]: {
    question: r`In a long-term relationship, one partner realizes that he receives far more than he contributes. Instead of feeling pleased, he feels uneasy and guilty and starts doing more. Which statement correctly explains this?`,
    options: [r`Exchange theory: rewards above costs cause distress`, r`Equity theory: being under-benefited feels rewarding`, r`Equity theory: being over-benefited causes distress`, r`Exchange theory: costs above rewards feel satisfying`],
    correctAnswer: 2,
    explanation: r`Equity theory adds to social exchange theory the claim that an unfair ratio distresses both partners, including the over-benefited one, who then tries to restore balance. Social exchange theory alone predicts satisfaction when rewards exceed costs, so it cannot explain his guilt, and neither theory says being under-benefited or bearing high costs feels good.`,
  },
  [r`{{c1::Kin selection}} explains helping relatives through inclusive fitness; {{c2::reciprocal altruism}} (Trivers) explains helping nonkin who can repay later.`]: {
    question: r`Female ground squirrels give loud alarm calls that draw a predator's attention to themselves. They call far more often when sisters and daughters are nearby than when only unrelated squirrels are nearby. Which explanation fits this pattern?`,
    options: [r`Reciprocal altruism among nonkin`, r`Empathy-altruism from concern`, r`Social exchange of net rewards`, r`Kin selection by inclusive fitness`],
    correctAnswer: 3,
    explanation: r`Helping that tracks genetic relatedness is explained by kin selection: the caller's genes benefit through the relatives she saves, which is inclusive fitness. Reciprocal altruism would predict calling for unrelated animals that can repay later, and empathy-altruism and social exchange are proximate human accounts that do not explain why relatedness matters.`,
  },
  [r`Repeated, unreinforced exposure to a stimulus increases liking, an effect named {{c1::mere exposure}} and demonstrated by {{c2::Zajonc}}.`]: {
    question: r`A woman attends a large lecture class 15 times during a term, always sitting silently and never speaking to anyone. At the end of the term, students rate her photo as more likeable than photos of women who never attended. Which effect does this show?`,
    options: [r`The halo effect at work`, r`The mere exposure effect`, r`The reciprocity of liking`, r`The similarity effect`],
    correctAnswer: 1,
    explanation: r`Repeated, unreinforced exposure to a stimulus increases liking, which is the mere exposure effect described by Zajonc. The halo effect would require a positive trait such as attractiveness that differs between the women, reciprocity requires that she showed liking for the students, and similarity requires shared attitudes; she never interacted with anyone.`,
  },
  [r`A {{c1::stereotype}} is the cognitive belief about a group, {{c2::prejudice}} is the affective evaluation, and discrimination is the behavior.`]: {
    question: r`A recruiter is convinced that graduates of one particular college are poor communicators. He feels no dislike toward them and scores their interviews exactly as he scores everyone else's. What is present in this case?`,
    options: [r`A stereotype, a belief about a group`, r`A prejudice, a feeling about a group`, r`Discrimination, an act toward a group`, r`Ethnocentrism, a ranking of cultures`],
    correctAnswer: 0,
    explanation: r`A generalized belief about a group is a stereotype, the cognitive component. Prejudice is the affective evaluation, which he lacks because he feels no dislike, and discrimination is behavior, which is absent because he scores everyone the same way. Ethnocentrism is judging another culture by the standards of one's own.`,
  },
  [r`A fundraiser first asks for a 500 dollar gift, is refused, then asks for 50 and gets it. Name the technique and its two mechanisms.`]: {
    question: r`A volunteer asks parents to mentor a child every week for two years, and all refuse. The same volunteer immediately asks them to chaperone a single zoo trip. Compared with parents who are asked only about the zoo trip, how does agreement change, and why?`,
    options: [r`It falls, since saying no once makes refusal consistent`, r`It rises, since an earlier small yes changed their self-image`, r`It rises, since the retreat invites a concession in return`, r`It stays the same, since the two requests are unrelated`],
    correctAnswer: 2,
    explanation: r`This is door-in-the-face: backing down from a large request looks like a concession, which people feel they should reciprocate, and the small request also looks minor by contrast. An earlier small yes changing self-image is the foot-in-the-door mechanism, and no yes was given here. The technique reliably raises agreement, so falling or unchanged agreement is wrong.`,
  },
}
